package org.marketreview.nativeapp;
import java.util.*;
import org.json.*;
/** Reads only injected in-memory instruments. No clock, transport, file or database access. */
public final class EtfHostSnapshot {
 private EtfHostSnapshot(){}
 private static void need(boolean v,String message){if(!v)throw new IllegalArgumentException(message);}
 private static boolean validId(String id){return id.matches("^(SH|SZ|BJ):etf:[0-9]{6}$");}
 private static boolean transientRow(JSONObject r){return r.opt("transient") instanceof Boolean&&r.optBoolean("transient");}
 private static JSONObject object(JSONObject r,String key){JSONObject o=r.optJSONObject(key);return o==null?new JSONObject():o;}
 private static JSONObject pick(JSONObject o,String...keys)throws Exception{JSONObject out=new JSONObject();for(String k:keys)if(o.has(k))out.put(k,o.opt(k));return out;}
 private static boolean identity(JSONObject r){Object value=r.opt("id"),name=r.opt("name");if(!(value instanceof String)||!validId((String)value)||transientRow(r)||!(name instanceof String)||((String)name).trim().isEmpty()||((String)name).length()>128)return false;String id=(String)value,symbol=id.substring(0,2).toLowerCase(Locale.ROOT)+id.substring(id.lastIndexOf(':')+1);return (!r.has("symbol")||symbol.equals(r.opt("symbol")))&&(!object(r,"quote").has("symbol")||symbol.equals(object(r,"quote").opt("symbol")));}
 private static Map<String,Integer> counts(JSONArray rows){Map<String,Integer> n=new HashMap<>();for(int i=0;i<rows.length();i++){JSONObject r=rows.optJSONObject(i);if(r==null)continue;Object id=r.opt("id");if(id instanceof String&&validId((String)id)&&!transientRow(r))n.merge((String)id,1,Integer::sum);}return n;}
 private static JSONObject target(JSONArray rows,String id)throws Exception{need(rows.length()<=3000,"宿主载入清单超过3000项");need(validId(id),"只接受完整ETF身份");need(counts(rows).getOrDefault(id,0)==1,"ETF已移除或身份不唯一");for(int i=0;i<rows.length();i++){JSONObject r=rows.optJSONObject(i);if(r!=null&&id.equals(r.opt("id"))&&!transientRow(r)){need(identity(r)&&r.opt("symbol") instanceof String,"ETF实际符号或名称缺失/不符");int symbolCount=0;for(int j=0;j<rows.length();j++){JSONObject other=rows.optJSONObject(j);if(other!=null&&r.opt("symbol").equals(other.opt("symbol")))symbolCount++;}need(symbolCount==1,"宿主存在共用报价符号的不同证券身份");JSONObject safe=EtfMonitorModel.snapshot(new JSONObject().put("schema","native-etf-monitor/v1").put("provider","host-held-etf").put("items",new JSONArray().put(pick(r,"id","name"))));return pick(r,"id","symbol").put("name",safe.getJSONArray("items").getJSONObject(0).get("name"));}}throw new IllegalArgumentException("ETF未在已有清单中");}
 public static JSONObject adapt(JSONArray rows,Object receivedAt)throws Exception{
  need(rows.length()<=3000,"宿主载入清单超过3000项");JSONArray items=new JSONArray();Map<String,Integer> n=counts(rows);int nonEtf=0,transientCount=0,invalid=0,duplicates=0,truncated=0,minuteMismatch=0;
  for(int i=0;i<rows.length();i++){JSONObject r=rows.optJSONObject(i);if(r==null)r=new JSONObject();String id=r.opt("id") instanceof String?(String)r.opt("id"):"";if(!validId(id)){nonEtf++;continue;}if(transientRow(r)){transientCount++;continue;}if(n.getOrDefault(id,0)!=1){duplicates++;continue;}if(!identity(r)){invalid++;continue;}if(items.length()>=2000){truncated++;continue;}
   JSONObject quote=pick(object(r,"quote"),"source","sourceTime","tradeDate","tradeTime","checkedAt","cached","error","price","changePercent","amount");for(String k:new String[]{"source","tradeDate","tradeTime","error"})if(quote.has(k)&&!quote.isNull(k)&&!(quote.opt(k) instanceof String))quote.remove(k);
   JSONObject rawMeta=object(r,"minuteMeta"),meta=pick(rawMeta,"source","intervalMinutes","sampling","amountUnit","checkedAt","fetchedAt","stale","cached");if(meta.has("source")&&!meta.isNull("source")&&!(meta.opt("source") instanceof String))meta.remove("source");if(meta.has("sampling"))meta.put("sampling",pick(object(meta,"sampling"),"intervalMinutes"));
   JSONArray input=r.optJSONArray("minute");if(input==null)input=rawMeta.optJSONArray("rows");if(input==null)input=new JSONArray();boolean mismatch=r.optJSONArray("minute")!=null&&rawMeta.optJSONArray("rows")!=null&&!EtfMonitorModel.equal(input,rawMeta.getJSONArray("rows"));if(input.length()>512||mismatch){input=new JSONArray();meta=new JSONObject();minuteMismatch++;}
   JSONArray minute=new JSONArray();for(int j=0;j<input.length();j++){JSONObject v=input.optJSONObject(j);if(v!=null)minute.put(pick(v,"time","price","close","amount","valid","duplicate"));}meta.put("rows",minute);items.put(new JSONObject().put("id",id).put("name",r.get("name")).put("quote",quote).put("minuteInput",meta));
  }
  JSONObject snapshot=EtfMonitorModel.snapshot(new JSONObject().put("schema","native-etf-monitor/v1").put("provider","host-held-etf").put("receivedAt",receivedAt==null?JSONObject.NULL:receivedAt).put("items",items));
  return new JSONObject().put("snapshot",snapshot).put("coverage",new JSONObject().put("scope","loaded-non-transient-etf-sample").put("completeMarket",false).put("loadedInstrumentCount",rows.length()).put("includedEtfCount",items.length()).put("excludedNonEtfCount",nonEtf).put("excludedTransientCount",transientCount).put("excludedInvalidCount",invalid).put("excludedDuplicateRowCount",duplicates).put("truncatedEtfCount",truncated).put("unusableMinuteCount",minuteMismatch).put("note","已有ETF清单样本；逐项来源时点，不是全市场同刻榜单"));
 }
 public static JSONObject adapt(JSONArray rows)throws Exception{return adapt(rows,JSONObject.NULL);}
 public static JSONObject request(JSONArray rows,JSONObject selection)throws Exception{need(selection.opt("period") instanceof String&&selection.opt("ids") instanceof JSONArray,"刷新选择字段无效");String period=selection.getString("period");JSONArray ids=selection.getJSONArray("ids");need((period.equals("quote")||period.equals("minute"))&&ids.length()>0&&ids.length()<=24&&(!period.equals("minute")||ids.length()==1),"刷新须当前页最多24个报价或一个ETF分钟");JSONArray targets=new JSONArray();Set<String> seen=new HashSet<>();for(int i=0;i<ids.length();i++){Object v=ids.opt(i);need(v instanceof String&&seen.add((String)v),"刷新身份无效或重复");targets.put(target(rows,(String)v));}return new JSONObject().put("ids",new JSONArray(ids.toString())).put("period",period).put("targets",targets);}
 public static JSONObject chart(JSONArray rows,String id,String period)throws Exception{need(Arrays.asList("quote","minute","day","week","month","year").contains(period),"不支持的原生行情周期");return target(rows,id).put("period",period);}
 public static boolean accepts(String token,String reply,boolean active){return active&&token!=null&&!token.isEmpty()&&token.length()<=80&&token.equals(reply);}
}
